"""Multimodal AI Companion Robot Controller (PC)"""
import threading
import requests
import cv2
import speech_recognition as sr

ESP_IP = "192.168.0.50"  # ESP32 IP
running = True

def listen_audio():
    r = sr.Recognizer()
    with requests.get(f"http://{ESP_IP}:8081/", stream=True) as resp:
        resp.raw.read(44)
        while running:
            pcm = resp.raw.read(16000 * 2 * 2)
            if not pcm:
                break
            try:
                text = r.recognize_google(sr.AudioData(pcm, 16000, 2), language="en-US").lower()
                if "smile" in text or "happy" in text:
                    requests.get(f"http://{ESP_IP}:8081/ai?action=HAPPY", timeout=0.5)
                elif "surprise" in text:
                    requests.get(f"http://{ESP_IP}:8081/ai?action=SURPRISED", timeout=0.5)
                elif "love" in text:
                    requests.get(f"http://{ESP_IP}:8081/ai?action=LOVE", timeout=0.5)
            except sr.UnknownValueError:
                pass

threading.Thread(target=listen_audio, daemon=True).start()

cap = cv2.VideoCapture(f"http://{ESP_IP}:8080/")
while cap.isOpened():
    ret, frame = cap.read()
    if not ret:
        break
    cv2.imshow("Multimodal AI", frame)
    if cv2.waitKey(1) & 0xFF == ord("q"):
        break

running = False
cap.release()
cv2.destroyAllWindows()
